# PTX source for MSE mean kernel (fp16 inputs, fp16 output)
PTX_SOURCE = r"""
.version 7.2
.target sm_80
.address_size 64

.visible .entry mse_mean_kernel(
    .param .u64 a_ptr,
    .param .u64 b_ptr,
    .param .u64 out_ptr,
    .param .u64 N_param
)
{
    // Registers
    .reg .pred   %p<2>;
    .reg .b64    %rd<12>;
    .reg .f32    %f<6>;
    .reg .f16    %h<3>;
    .reg .s32    %r<5>;

    // Load kernel parameters
    ld.param.u64    %rd1, [a_ptr];
    ld.param.u64    %rd2, [b_ptr];
    ld.param.u64    %rd3, [out_ptr];
    ld.param.u64    %rd4, [N_param];

    // Compute thread id and stride
    mov.u32         %r1, %ctaid.x;
    mov.u32         %r2, %ntid.x;
    mul.lo.u32      %r3, %r1, %r2;          // blockIdx.x * blockDim.x
    mov.u32         %r4, %tid.x;
    add.u32         %r0, %r3, %r4;          // global thread index

    // stride = gridDim.x * blockDim.x
    mov.u32         %r5, %nctaid.x;
    mul.lo.u32      %r5, %r5, %r2;          // stride

    // Cast N to float for division
    cvt.rn.f32.u64  %f0, %rd4;               // N as float

    // Loop over elements
LOOP:
    setp.ge.s32     %p0, %r0, %rd4;         // if idx >= N exit
    @%p0 bra        END_LOOP;

    // Load half a, b
    mul.wide.u32    %rd5, %r0, 2;           // offset in bytes (fp16 = 2 bytes)
    add.u64         %rd6, %rd1, %rd5;
    add.u64         %rd7, %rd2, %rd5;
    ld.global.f16   %h0, [%rd6];
    ld.global.f16   %h1, [%rd7];

    // Convert to float
    cvt.rn.f32.f16  %f1, %h0;
    cvt.rn.f32.f16  %f2, %h1;

    // diff = a - b
    sub.f32         %f3, %f1, %f2;

    // sq = diff * diff
    mul.f32         %f4, %f3, %f3;

    // contribution = sq / N
    div.f32         %f5, %f4, %f0;

    // atomic add to accumulator (interpreted as float32)
    // out_ptr is a pointer to fp16 tensor, we treat it as float32 for accumulation
    cvt.rn.f32.u64  %rd8, %rd3;               // address as 64-bit
    atom.add.f32    %f6, [%rd8], %f5;        // atomic add

    // advance idx
    add.u32         %r0, %r0, %r5;
    bra.uni         LOOP;

END_LOOP:
    // Ensure all atomic adds are done before final write
    bar.sync 0;

    // Only thread (0,0,0) writes the final mean to half output
    setp.eq.s32     %p1, %tid.x, 0;
    setp.eq.s32     %p2, %ctaid.x, 0;
    and.pred        %p1, %p1, %p2;
    @%p1 {
        // Load the accumulated float value
        ld.global.f32 %f0, [%rd8];
        // Convert to half (fp16) with round-to-nearest
        cvt.rn.f16.f32 %h2, %f0;
        // Store back as half
        st.global.f16 [%rd3], %h2;
    }

    ret;
}
"""

# ModelNew class that uses the PTX kernel
class ModelNew:
    def __init__(self):
        # Load the PTX module using the harness API
        self.module = ptx_load(PTX_SOURCE)
        self.kernel_name = "mse_mean_kernel"

    def forward(self, predictions, targets):
        """
        predictions: torch.Tensor of dtype torch.float16, device='cuda'
        targets:     torch.Tensor of same shape and dtype
        Returns: torch scalar tensor (float16) containing the MSE mean.
        """
        assert predictions.is_cuda and targets.is_cuda
        assert predictions.dtype == torch.float16
        assert predictions.shape == targets.shape

        # Create output tensor (scalar) and zero it (used as accumulator)
        out = torch.empty((), dtype=torch.float16, device='cuda')
        out.fill_(0.0)

        # Total number of elements (int64)
        N = predictions.numel()
        N_tensor = torch.tensor(N, dtype=torch.int64, device='cuda')

        # Launch configuration
        threads_per_block = 256
        num_blocks = (N + threads_per_block - 1) // threads_per_block

        # Prepare arguments (as raw pointers)
        args = [
            predictions.data_ptr(),
            targets.data_ptr(),
            out.data_ptr(),
            N_tensor.item()
        ]

        # Launch the kernel
        ptx_launch(
            self.module,
            self.kernel_name,
            grid=(num_blocks, 1, 1),
            block=(threads_per_block, 1, 1),
            args=args
        )

        return out
